-- =====================================================================
-- DuongTech · service-product · dữ liệu mẫu
-- 179 mẫu laptop có thật, thu thập từ trang cellphones.com.vn
-- (tên máy, giá bán, ảnh sản phẩm). Ảnh đã tải về frontend/public/products/cps/.
-- Mô tả viết theo nhóm hàng vì trang nguồn không công khai thông số từng máy.
-- Điểm đánh giá và số lượt đánh giá là SỐ GIẢ LẬP phục vụ bản demo (trang nguồn
-- không công khai hai chỉ số này); một phần sản phẩm để 0 nên hiển thị nhãn "Mới".
-- SQL thuần (không dùng khối thủ tục) để Spring Boot tách câu lệnh đúng theo ";".
-- Chạy đúng một lần: nếu đã có sản phẩm ảnh /products/cps/ thì bỏ qua toàn bộ.
-- =====================================================================

-- 0a) Nới rộng cột giá. Cột cũ là numeric(10,2) nên chỉ chứa được tới 99.999.999đ,
--     trong khi laptop cao cấp đã vượt 100 triệu. Trên CSDL mới câu này không đổi gì.
ALTER TABLE IF EXISTS products ALTER COLUMN price TYPE numeric(15,2);

-- 0b) Dọn bộ dữ liệu mẫu cũ (ảnh loremflickr không còn tải được).
DELETE FROM reviews WHERE NOT EXISTS (SELECT 1 FROM products WHERE image_url LIKE '/products/cps/%');
DELETE FROM products WHERE NOT EXISTS (SELECT 1 FROM products p2 WHERE p2.image_url LIKE '/products/cps/%');
DELETE FROM categories WHERE NOT EXISTS (SELECT 1 FROM products WHERE image_url LIKE '/products/cps/%');

-- 1) Danh mục
INSERT INTO categories (id, name, description, display_order, active, created_at, updated_at)
SELECT v.id, v.name, v.description, v.ord, true, NOW(), NOW()
FROM (VALUES
    (1::bigint, 'Laptop Gaming', 'Laptop chơi game hiệu năng cao, card đồ hoạ rời, màn tần số quét cao.', 1::int),
    (2::bigint, 'Laptop Văn phòng', 'Laptop mỏng nhẹ, pin lâu, phù hợp công việc văn phòng và học tập.', 2::int),
    (3::bigint, 'Laptop Đồ hoạ', 'Máy trạm cho thiết kế, dựng phim, màn hình chuẩn màu.', 3::int),
    (4::bigint, 'Ultrabook', 'Ultrabook siêu mỏng nhẹ, di động cao, pin cả ngày.', 4::int)
) AS v(id, name, description, ord)
WHERE NOT EXISTS (SELECT 1 FROM categories);

